import{_ as s,o as a,c as p,am as e}from"./chunks/framework.CiF4W93w.js";const d=JSON.parse('{"title":"消息队列_RabbitMQ_基础使用","description":"","frontmatter":{"title":"消息队列_RabbitMQ_基础使用","excerpt":"RabbitMQ 的几种交换机类型及其在 Spring Boot 中的应用方式","date":"2024-02-27 19:01:21","updated":"2024-02-27 19:01:21"},"headers":[],"relativePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础使用.md","filePath":"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础使用.md","lastUpdated":null}'),l={name:"中间件/中间件 - 消息队列/MQ RabbitMQ/消息队列_RabbitMQ_基础使用.md"};function i(t,n,c,o,r,u){return a(),p("div",null,[...n[0]||(n[0]=[e(`<p>交换机类型</p><p>（交换机 → 队列）</p><ul><li>Direct Exchange <ul><li><code>binding key</code> 与消息的 <code>routing key</code> 完全匹配队列</li></ul></li><li>Topic Exchange <ul><li>模式匹配</li></ul></li><li>Fanout Exchange</li><li>广播（忽略 <code>routing key</code> ）</li><li>Headers Exchange <ul><li>不依赖 <code>routing key</code>，头部属性匹配</li></ul></li></ul><h3 id="rabbitmq广播和直接模式示例" tabindex="-1">RabbitMQ广播和直接模式示例 <a class="header-anchor" href="#rabbitmq广播和直接模式示例" aria-label="Permalink to &quot;RabbitMQ广播和直接模式示例&quot;">​</a></h3><p>项目参考： <a href="https://gitee.com/yidao620/springboot-bucket" target="_blank" rel="noreferrer">https://gitee.com/yidao620/springboot-bucket</a></p><p>这个项目的最后更新时间是五年前， 这里建议单独打开一下 springboot-rabbitmq</p><p>本地的 maven 版本是 3.5.2 , springboot-rabbitmq 依赖中的 maven-compiler-plugin 改为了 3.6.1 后没有报错</p><p>在 SpringBoot 中，使用消息队列需要引入 amqp 的依赖</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;  </span></span>
<span class="line"><span>   &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;  </span></span>
<span class="line"><span>   &lt;artifactId&gt;spring-boot-starter-amqp&lt;/artifactId&gt;  </span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>yml 配置内容</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spring:  </span></span>
<span class="line"><span>  profiles: dev  </span></span>
<span class="line"><span>  rabbitmq:  </span></span>
<span class="line"><span>    host: 127.0.0.1  </span></span>
<span class="line"><span>    port: 5672  </span></span>
<span class="line"><span>    username: guest  </span></span>
<span class="line"><span>    password: guest</span></span></code></pre></div><h4 id="配置类" tabindex="-1">配置类 <a class="header-anchor" href="#配置类" aria-label="Permalink to &quot;配置类&quot;">​</a></h4><p>在这个项目中，定义了一个配置类 RabbitConfig</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package com.xncoding.pos.config;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import org.slf4j.Logger;</span></span>
<span class="line"><span>import org.slf4j.LoggerFactory;</span></span>
<span class="line"><span>import org.springframework.amqp.core.*;</span></span>
<span class="line"><span>import org.springframework.amqp.rabbit.core.RabbitTemplate;</span></span>
<span class="line"><span>import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;</span></span>
<span class="line"><span>import org.springframework.beans.factory.annotation.Qualifier;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Bean;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Configuration;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import javax.annotation.Resource;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * RabbitConfig</span></span>
<span class="line"><span> *</span></span>
<span class="line"><span> * @version 1.0</span></span>
<span class="line"><span> * @since 2018/3/1</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class RabbitConfig {</span></span>
<span class="line"><span>    @Resource</span></span>
<span class="line"><span>    private RabbitTemplate rabbitTemplate;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 定制化 AMQP 模版。</span></span>
<span class="line"><span>     * 设置消息转换器、编码、消息确认和返回回调。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the amqp template</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public AmqpTemplate amqpTemplate() {</span></span>
<span class="line"><span>        Logger log = LoggerFactory.getLogger(RabbitTemplate.class);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 使用 Jackson 作为消息转换器，自动将消息转换为 JSON 格式</span></span>
<span class="line"><span>        rabbitTemplate.setMessageConverter(new Jackson2JsonMessageConverter());</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 设置字符编码为 UTF-8</span></span>
<span class="line"><span>        rabbitTemplate.setEncoding(&quot;UTF-8&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 消息发送失败时返回到队列，需要在配置文件中设置 publisher-returns: true</span></span>
<span class="line"><span>        rabbitTemplate.setMandatory(true);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 定义消息发送失败的回调</span></span>
<span class="line"><span>        rabbitTemplate.setReturnCallback((message, replyCode, replyText, exchange, routingKey) -&gt; {</span></span>
<span class="line"><span>            String correlationId = message.getMessageProperties().getCorrelationIdString();</span></span>
<span class="line"><span>            log.debug(&quot;消息：{} 发送失败, 应答码：{} 原因：{} 交换机: {}  路由键: {}&quot;, correlationId, replyCode, replyText, exchange, routingKey);</span></span>
<span class="line"><span>        });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 定义消息发送到交换机确认回调，需要在配置文件中设置 publisher-confirms: true</span></span>
<span class="line"><span>        rabbitTemplate.setConfirmCallback((correlationData, ack, cause) -&gt; {</span></span>
<span class="line"><span>            if (ack) {</span></span>
<span class="line"><span>                log.debug(&quot;消息发送到exchange成功,id: {}&quot;, correlationData.getId());</span></span>
<span class="line"><span>            } else {</span></span>
<span class="line"><span>                log.debug(&quot;消息发送到exchange失败,原因: {}&quot;, cause);</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        return rabbitTemplate;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Direct Exchange 配置部分</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明 Direct 交换机。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the exchange</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;directExchange&quot;)</span></span>
<span class="line"><span>    public Exchange directExchange() {</span></span>
<span class="line"><span>        // 创建并返回一个持久化的 Direct 交换机</span></span>
<span class="line"><span>        return ExchangeBuilder.directExchange(&quot;DIRECT_EXCHANGE&quot;).durable(true).build();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明队列。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the queue</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;directQueue&quot;)</span></span>
<span class="line"><span>    public Queue directQueue() {</span></span>
<span class="line"><span>        // 创建并返回一个持久化的队列</span></span>
<span class="line"><span>        return QueueBuilder.durable(&quot;DIRECT_QUEUE&quot;).build();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 将队列绑定到交换机。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param queue    the queue</span></span>
<span class="line"><span>     * @param exchange the exchange</span></span>
<span class="line"><span>     * @return the binding</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding directBinding(@Qualifier(&quot;directQueue&quot;) Queue queue,</span></span>
<span class="line"><span>                                 @Qualifier(&quot;directExchange&quot;) Exchange exchange) {</span></span>
<span class="line"><span>        // 将队列绑定到交换机，使用路由键 &quot;DIRECT_ROUTING_KEY&quot;</span></span>
<span class="line"><span>        return BindingBuilder.bind(queue).to(exchange).with(&quot;DIRECT_ROUTING_KEY&quot;).noargs();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Fanout Exchange 配置部分</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明 Fanout 交换机。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the exchange</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;fanoutExchange&quot;)</span></span>
<span class="line"><span>    public FanoutExchange fanoutExchange() {</span></span>
<span class="line"><span>        // 创建并返回一个持久化的 Fanout 交换机</span></span>
<span class="line"><span>        return (FanoutExchange) ExchangeBuilder.fanoutExchange(&quot;FANOUT_EXCHANGE&quot;).durable(true).build();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明队列 A。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the queue</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;fanoutQueueA&quot;)</span></span>
<span class="line"><span>    public Queue fanoutQueueA() {</span></span>
<span class="line"><span>        // 创建并返回一个持久化的队列 A</span></span>
<span class="line"><span>        return QueueBuilder.durable(&quot;FANOUT_QUEUE_A&quot;).build();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 声明队列 B。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @return the queue</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean(&quot;fanoutQueueB&quot;)</span></span>
<span class="line"><span>    public Queue fanoutQueueB() {</span></span>
<span class="line"><span>        // 创建并返回一个持久化的队列 B</span></span>
<span class="line"><span>        return QueueBuilder.durable(&quot;FANOUT_QUEUE_B&quot;).build();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 将队列 A 绑定到 Fanout 交换机。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param queue          the queue</span></span>
<span class="line"><span>     * @param fanoutExchange the fanout exchange</span></span>
<span class="line"><span>     * @return the binding</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding bindingA(@Qualifier(&quot;fanoutQueueA&quot;) Queue queue,</span></span>
<span class="line"><span>                            @Qualifier(&quot;fanoutExchange&quot;) FanoutExchange fanoutExchange) {</span></span>
<span class="line"><span>        // 将队列 A 绑定到 Fanout 交换机</span></span>
<span class="line"><span>        return BindingBuilder.bind(queue).to(fanoutExchange);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 将队列 B 绑定到 Fanout 交换机。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param queue          the queue</span></span>
<span class="line"><span>     * @param fanoutExchange the fanout exchange</span></span>
<span class="line"><span>     * @return the binding</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding bindingB(@Qualifier(&quot;fanoutQueueB&quot;) Queue queue,</span></span>
<span class="line"><span>                            @Qualifier(&quot;fanoutExchange&quot;) FanoutExchange fanoutExchange) {</span></span>
<span class="line"><span>        // 将队列 B 绑定到 Fanout 交换机</span></span>
<span class="line"><span>        return BindingBuilder.bind(queue).to(fanoutExchange);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个 <code>RabbitConfig</code> 配置类通过 <code>@Bean</code> 注解声明了多个 Spring Bean，用于设置 RabbitMQ 的不同组件。</p><p>它涵盖了消息模板的定制、交换机和队列的声明，以及队列与交换机的绑定。</p><p>这样的配置提供了灵活的方式来定义消息传递的行为，包括消息格式、路由策略和队列管理，适用于不同的消息处理需求。</p><p>通过这种方式，可以在 Spring 应用中轻松地使用 RabbitMQ 进行高效的消息通信。</p><hr><p>通过广播方式发送消息</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/**</span></span>
<span class="line"><span> * 发送广播模式的消息。</span></span>
<span class="line"><span> * </span></span>
<span class="line"><span> * @param p 要发送的消息内容</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>public void broadcast(String p) {</span></span>
<span class="line"><span>    // 创建 CorrelationData 对象，带有一个唯一的标识符。</span></span>
<span class="line"><span>    // 这个标识符用于消息确认过程中识别消息。</span></span>
<span class="line"><span>    CorrelationData correlationData = new CorrelationData(UUID.randomUUID().toString());</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 使用 RabbitTemplate 将消息发送到指定的交换机。</span></span>
<span class="line"><span>    // 参数1: 交换机名称 - 这里是 &quot;FANOUT_EXCHANGE&quot;。</span></span>
<span class="line"><span>    // 参数2: 路由键 - 在 Fanout 交换机中，路由键会被忽略，所以这里传递一个空字符串。</span></span>
<span class="line"><span>    // 参数3: 消息内容 - 这里是传入的参数 p。</span></span>
<span class="line"><span>    // 参数4: CorrelationData - 包含消息的唯一标识符，用于消息跟踪和确认。</span></span>
<span class="line"><span>    rabbitTemplate.convertAndSend(&quot;FANOUT_EXCHANGE&quot;, &quot;&quot;, p, correlationData);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在前面的配置类中，是声明了 Fanout 交换机， 并且绑定两个队列在这个交换机上。</p><h4 id="生产者类" tabindex="-1">生产者类 <a class="header-anchor" href="#生产者类" aria-label="Permalink to &quot;生产者类&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package com.xncoding.pos.service;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import org.slf4j.Logger;</span></span>
<span class="line"><span>import org.slf4j.LoggerFactory;</span></span>
<span class="line"><span>import org.springframework.amqp.rabbit.core.RabbitTemplate;</span></span>
<span class="line"><span>import org.springframework.amqp.rabbit.support.CorrelationData;</span></span>
<span class="line"><span>import org.springframework.stereotype.Service;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import javax.annotation.Resource;</span></span>
<span class="line"><span>import java.util.UUID;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * 消息发送服务</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class SenderService {</span></span>
<span class="line"><span>    private Logger logger = LoggerFactory.getLogger(this.getClass());</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Resource</span></span>
<span class="line"><span>    private RabbitTemplate rabbitTemplate;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 测试广播模式.</span></span>
<span class="line"><span>     * 在广播模式下，消息会被发送到所有绑定到交换机的队列。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param p 要发送的消息内容</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public void broadcast(String p) {</span></span>
<span class="line"><span>        // 为每个消息创建一个带唯一标识符的 CorrelationData 对象</span></span>
<span class="line"><span>        CorrelationData correlationData = new CorrelationData(UUID.randomUUID().toString());</span></span>
<span class="line"><span>        // 将消息发送到 FANOUT_EXCHANGE 交换机，路由键为空字符串</span></span>
<span class="line"><span>        rabbitTemplate.convertAndSend(&quot;FANOUT_EXCHANGE&quot;, &quot;&quot;, p, correlationData);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 测试Direct模式.</span></span>
<span class="line"><span>     * 在Direct模式下，消息会被路由到具有指定路由键的队列。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param p 要发送的消息内容</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public void direct(String p) {</span></span>
<span class="line"><span>        // 为每个消息创建一个带唯一标识符的 CorrelationData 对象</span></span>
<span class="line"><span>        CorrelationData correlationData = new CorrelationData(UUID.randomUUID().toString());</span></span>
<span class="line"><span>        // 将消息发送到 DIRECT_EXCHANGE 交换机，并指定路由键</span></span>
<span class="line"><span>        rabbitTemplate.convertAndSend(&quot;DIRECT_EXCHANGE&quot;, &quot;DIRECT_ROUTING_KEY&quot;, p, correlationData);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="消费者类" tabindex="-1">消费者类 <a class="header-anchor" href="#消费者类" aria-label="Permalink to &quot;消费者类&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package com.xncoding.pos.mq;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import com.rabbitmq.client.Channel;</span></span>
<span class="line"><span>import org.slf4j.Logger;</span></span>
<span class="line"><span>import org.slf4j.LoggerFactory;</span></span>
<span class="line"><span>import org.springframework.amqp.core.Message;</span></span>
<span class="line"><span>import org.springframework.amqp.rabbit.annotation.RabbitListener;</span></span>
<span class="line"><span>import org.springframework.stereotype.Component;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import java.io.IOException;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * 消息监听器</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>@Component</span></span>
<span class="line"><span>public class Receiver {</span></span>
<span class="line"><span>    private static final Logger log = LoggerFactory.getLogger(Receiver.class);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * FANOUT广播队列监听一.</span></span>
<span class="line"><span>     * 在 FANOUT_QUEUE_A 队列上监听消息。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param message 接收到的消息</span></span>
<span class="line"><span>     * @param channel 通信通道</span></span>
<span class="line"><span>     * @throws IOException 在消息确认过程中可能抛出的异常</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @RabbitListener(queues = {&quot;FANOUT_QUEUE_A&quot;})</span></span>
<span class="line"><span>    public void on(Message message, Channel channel) throws IOException {</span></span>
<span class="line"><span>        // 确认消息已被正确接收</span></span>
<span class="line"><span>        channel.basicAck(message.getMessageProperties().getDeliveryTag(), true);</span></span>
<span class="line"><span>        // 记录接收到的消息</span></span>
<span class="line"><span>        log.debug(&quot;FANOUT_QUEUE_A &quot; + new String(message.getBody()));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * FANOUT广播队列监听二.</span></span>
<span class="line"><span>     * 在 FANOUT_QUEUE_B 队列上监听消息。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param message 接收到的消息</span></span>
<span class="line"><span>     * @param channel 通信通道</span></span>
<span class="line"><span>     * @throws IOException 在消息确认过程中可能抛出的异常</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @RabbitListener(queues = {&quot;FANOUT_QUEUE_B&quot;})</span></span>
<span class="line"><span>    public void t(Message message, Channel channel) throws IOException {</span></span>
<span class="line"><span>        // 确认消息已被正确接收</span></span>
<span class="line"><span>        channel.basicAck(message.getMessageProperties().getDeliveryTag(), true);</span></span>
<span class="line"><span>        // 记录接收到的消息</span></span>
<span class="line"><span>        log.debug(&quot;FANOUT_QUEUE_B &quot; + new String(message.getBody()));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * DIRECT模式.</span></span>
<span class="line"><span>     * 在 DIRECT_QUEUE 队列上监听消息。</span></span>
<span class="line"><span>     *</span></span>
<span class="line"><span>     * @param message 接收到的消息</span></span>
<span class="line"><span>     * @param channel 通信通道</span></span>
<span class="line"><span>     * @throws IOException 在消息确认过程中可能抛出的异常</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    @RabbitListener(queues = {&quot;DIRECT_QUEUE&quot;})</span></span>
<span class="line"><span>    public void message(Message message, Channel channel) throws IOException {</span></span>
<span class="line"><span>        // 确认消息已被正确接收</span></span>
<span class="line"><span>        channel.basicAck(message.getMessageProperties().getDeliveryTag(), true);</span></span>
<span class="line"><span>        // 记录接收到的消息</span></span>
<span class="line"><span>        log.debug(&quot;DIRECT &quot; + new String(message.getBody()));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>在生产者类（<code>SenderService</code>）中，两个方法分别演示了如何在广播（Fanout）和直接（Direct）模式下发送消息。</li><li>在消费者类（<code>Receiver</code>）中，每个方法都使用了 <code>@RabbitListener</code> 注解来监听特定的队列，并在接收到消息后执行相应的处理逻辑。</li></ul><p>这里由于你配置了接收的监听，因此当你发送的时候你就收到了这条消息，并且通过日志的方式打印了出来，如果需要比较明显一点的观察现象，可以加一个等待时间确保被消费。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 等待一段时间以确保消息被消费 </span></span>
<span class="line"><span>Thread.sleep(1000);</span></span></code></pre></div><h4 id="主题交换机-topic-exchange-的使用示例" tabindex="-1">主题交换机（Topic Exchange）的使用示例 <a class="header-anchor" href="#主题交换机-topic-exchange-的使用示例" aria-label="Permalink to &quot;主题交换机（Topic Exchange）的使用示例&quot;">​</a></h4><p>Topic Exchange 直接翻译的话叫做主题交换机，如果从用法上面翻译可能叫通配符交换机会更加贴切。</p><p>这种交换机是使用通配符去匹配，路由到对应的队列。通配符有两种：&quot;* &quot; 、 &quot;#&quot;。需要注意的是通配符前面必须要加上&quot;.&quot;符号。</p><p><code>*</code> 符号：有且只匹配一个词。比如 <code>a.*</code>可以匹配到&quot;a.b&quot;、&quot;a.c&quot;，但是匹配不了&quot;a.b.c&quot;。 <code>#</code> 符号：匹配一个或多个词。比如&quot;rabbit.#&quot;既可以匹配到&quot;rabbit.a.b&quot;、&quot;rabbit.a&quot;，也可以匹配到&quot;rabbit.a.b.c&quot;。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312121409207.png" alt="image.png"></p><blockquote><p>使用示例</p></blockquote><p>在前文的基础上，新增一些内容</p><p>配置类(更新配置类以包含一个主题交换机和两个队列，以及它们的绑定)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class RabbitConfig {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ... 其他配置 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Topic Exchange 配置</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public TopicExchange topicExchange() {</span></span>
<span class="line"><span>        return new TopicExchange(&quot;TOPIC_EXCHANGE&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Queue topicQueueOneWord() {</span></span>
<span class="line"><span>        return new Queue(&quot;TOPIC_QUEUE_ONE_WORD&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Queue topicQueueMultipleWords() {</span></span>
<span class="line"><span>        return new Queue(&quot;TOPIC_QUEUE_MULTIPLE_WORDS&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 绑定键 &quot;topic.*&quot; 只匹配一个单词</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding bindingTopicOneWord(Queue topicQueueOneWord, TopicExchange topicExchange) {</span></span>
<span class="line"><span>        return BindingBuilder.bind(topicQueueOneWord).to(topicExchange).with(&quot;topic.*&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 绑定键 &quot;topic.#&quot; 匹配零个或多个单词</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public Binding bindingTopicMultipleWords(Queue topicQueueMultipleWords, TopicExchange topicExchange) {</span></span>
<span class="line"><span>        return BindingBuilder.bind(topicQueueMultipleWords).to(topicExchange).with(&quot;topic.#&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>生产者类</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Service</span></span>
<span class="line"><span>public class SenderService {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ... 其他方法 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Resource</span></span>
<span class="line"><span>    private RabbitTemplate rabbitTemplate;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 发送消息到主题交换机</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    public void sendToTopic(String routingKey, String message) {</span></span>
<span class="line"><span>        rabbitTemplate.convertAndSend(&quot;TOPIC_EXCHANGE&quot;, routingKey, message);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>消费者类</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Component</span></span>
<span class="line"><span>public class Receiver {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ... 其他方法 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    private static final Logger log = LoggerFactory.getLogger(Receiver.class);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @RabbitListener(queues = {&quot;TOPIC_QUEUE_ONE_WORD&quot;})</span></span>
<span class="line"><span>    public void receiveFromTopicOneWord(Message message) {</span></span>
<span class="line"><span>        log.debug(&quot;Received in TOPIC_QUEUE_ONE_WORD: &quot; + new String(message.getBody()));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @RabbitListener(queues = {&quot;TOPIC_QUEUE_MULTIPLE_WORDS&quot;})</span></span>
<span class="line"><span>    public void receiveFromTopicMultipleWords(Message message) {</span></span>
<span class="line"><span>        log.debug(&quot;Received in TOPIC_QUEUE_MULTIPLE_WORDS: &quot; + new String(message.getBody()));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>测试类(发送消息并验证它们被正确路由到对应的队列：)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@SpringBootTest</span></span>
<span class="line"><span>public class RabbitMqTest {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ... 其他测试 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private SenderService senderService;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Test</span></span>
<span class="line"><span>    public void testTopicExchange() throws InterruptedException {</span></span>
<span class="line"><span>        // 发送消息，路由键匹配 &quot;topic.*&quot;，应该只被 TOPIC_QUEUE_ONE_WORD 接收</span></span>
<span class="line"><span>        senderService.sendToTopic(&quot;topic.one&quot;, &quot;Message for topic.one&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 发送消息，路由键匹配 &quot;topic.#&quot;，应该被两个队列接收</span></span>
<span class="line"><span>        senderService.sendToTopic(&quot;topic.one.two&quot;, &quot;Message for topic.one.two&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 等待一段时间以确保消息被消费</span></span>
<span class="line"><span>        Thread.sleep(1000);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>第一个测试消息使用路由键 &quot;topic.one&quot;，它符合 <code>*</code> 的匹配规则（匹配一个单词），因此只有 &quot;TOPIC_QUEUE_ONE_WORD&quot; 队列接收到这个消息。</li><li>第二个测试消息使用路由键 &quot;topic.one.two&quot;，它符合 <code>#</code> 的匹配规则（匹配多个单词），因此两个队列都接收到这个消息。</li></ul><p>运行测试后，通过日志输出可以验证这些匹配规则是否按预期工作。</p><blockquote><p>小结</p></blockquote><p>在 RabbitMQ中比较常用的三种模式是：直连(DirectExchange)，发布订阅(FanoutExchange)，通配符(TopicExchange)。</p><p>熟练运用这三种交换机类型，基本上可以解决大部分的业务场景。</p><p>通配符(TopicExchange)这种模式也可以达到直连(DirectExchange)和发布订阅(FanoutExchange)这两种的效果。</p><p>FanoutExchange不需要绑定routingKey，所以性能相对TopicExchange会好一些。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>交换机类型对比</p><table tabindex="0"><thead><tr><th>交换机类型</th><th>路由依据</th><th>支持路由键</th><th>匹配方式</th><th>场景举例</th></tr></thead><tbody><tr><td>Direct Exchange</td><td>routing key</td><td>是</td><td>完全匹配（binding key = routing key）</td><td>点对点消息</td></tr><tr><td>Topic Exchange</td><td>routing key（通配符）</td><td>是</td><td>模式匹配（*、# 通配符）</td><td>分类订阅/分组</td></tr><tr><td>Fanout Exchange</td><td>无</td><td>否</td><td>广播所有绑定队列</td><td>群发/广播</td></tr><tr><td>Headers Exchange</td><td>header属性</td><td>否</td><td>根据消息头属性</td><td>高级过滤场景</td></tr></tbody></table><p><strong>备注：</strong></p><ul><li><code>*</code> 通配符：匹配单个词。</li><li><code>#</code> 通配符：匹配零个或多个词。</li><li>Direct 适合精准投递，Topic 适合按主题分类，Fanout 适合全员广播，Headers 适合复杂消息属性过滤。</li></ul><p>希望这个表格可以帮助你快速理解各种交换机类型的区别！</p>`,57)])])}const b=s(l,[["render",i]]);export{d as __pageData,b as default};
